mapper.select:
select nvl(max(po_after) keep (dense_rank last order by po_at, po_no), 0)
from dc_point_history
where m_no = #{mNo}

select nvl(sum(
	greatest(
		e.po_amount - greatest(u.total_used - (e.cum_earn - e.po_amount), 0),
		0
	)
), 0)
from (
	select po_no, po_amount, po_ex,
		   sum(po_amount) over (order by po_at, po_no rows unbounded preceding) as cum_earn
	from dc_point_history
	where m_no = #{mNo} and po_type in ('EARN', 'RESTORE')
) e,
(
	select nvl(sum(abs(po_amount)), 0) as total_used
	from dc_point_history
	where m_no = #{mNo} and po_type in ('USE', 'EXPIRE')
) u
where e.po_ex is not null
  and e.po_ex between sysdate and sysdate + #{days}

select po_no, po_type, po_amount, po_after, po_reason, po_at, po_ex, po_order_no, m_no, ch_no, po_related_no
from dc_point_history
where po_no = #{poNo}

select count(*)
from dc_point_history
where m_no = #{mNo} and po_reason = #{poReason}

mapper.update:
update dc_point_history
set po_order_no = null
where po_order_no = #{orNo}
